import{Z as i,e as a,f as o,a0 as t}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"Fields","description":"","frontmatter":{},"headers":[],"relativePath":"guides/fields/index.md","filePath":"guides/fields/index.md","lastUpdated":1782532814000}'),r={name:"guides/fields/index.md"};function n(s,e,l,d,u,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h1><p>Field behaviour, calculations, option sources, and custom field authoring.</p><h2 id="bringing-your-craft-field-into-formie-custom-field-adapters" tabindex="-1"><a href="/guides/fields/bringing-your-craft-field-into-formie-custom-field-adapters">Bringing Your Craft Field Into Formie (Custom Field Adapters)</a> <a class="header-anchor" href="#bringing-your-craft-field-into-formie-custom-field-adapters" aria-label="Permalink to &quot;[Bringing Your Craft Field Into Formie (Custom Field Adapters)](/guides/fields/bringing-your-craft-field-into-formie-custom-field-adapters)&quot;">​</a></h2><p>Formie&#39;s <strong>Custom Field</strong> field type lets authors pick from supported Craft fields without you registering a separate Formie field for every plugin. Each supported option is an <strong>adapter</strong> — explicit Formie code that handles front-end rendering, validation, storage, exports, integrations, and GraphQL.</p><h2 id="calculations-field-in-detail" tabindex="-1"><a href="/guides/fields/calculations-field-in-detail">Calculations Field in Detail</a> <a class="header-anchor" href="#calculations-field-in-detail" aria-label="Permalink to &quot;[Calculations Field in Detail](/guides/fields/calculations-field-in-detail)&quot;">​</a></h2><p>This guide walks through Calculations syntax, field references, built-in functions, and practical examples. Use it alongside the <a href="/fields/calculations">Calculations field reference</a> when you are building pricing, scoring, or conditional output on a form.</p><h2 id="creating-a-custom-option-source-provider" tabindex="-1"><a href="/guides/fields/creating-a-custom-option-source-provider">Creating a Custom Option Source Provider</a> <a class="header-anchor" href="#creating-a-custom-option-source-provider" aria-label="Permalink to &quot;[Creating a Custom Option Source Provider](/guides/fields/creating-a-custom-option-source-provider)&quot;">​</a></h2><p>Custom option source providers expose server-resolved <code>{ label, value }</code> rows for Dropdown, Radio, Checkboxes, and Recipients fields. They appear in the form builder as <strong>Custom Provider</strong> when they declare support for the current field usage.</p><h2 id="creating-a-formie-field-type-from-scratch" tabindex="-1"><a href="/guides/fields/creating-a-formie-field-type-from-scratch">Creating a Formie Field Type from Scratch</a> <a class="header-anchor" href="#creating-a-formie-field-type-from-scratch" aria-label="Permalink to &quot;[Creating a Formie Field Type from Scratch](/guides/fields/creating-a-formie-field-type-from-scratch)&quot;">​</a></h2><p>In this guide we build a URL field from scratch — similar to Single-line Text, but with URL validation and optional front-end behaviour. By the end you will have a field that appears in the form builder palette, renders on the front end, validates submissions, and supports Theme Config.</p><h2 id="dynamic-option-sources-in-practice" tabindex="-1"><a href="/guides/fields/dynamic-option-sources-in-practice">Dynamic Option Sources in Practice</a> <a class="header-anchor" href="#dynamic-option-sources-in-practice" aria-label="Permalink to &quot;[Dynamic Option Sources in Practice](/guides/fields/dynamic-option-sources-in-practice)&quot;">​</a></h2><p>Dropdown, Radio, and Checkboxes fields can pull their options from several source types — not just a manually maintained table. This walkthrough shows when to use each option source and how they behave at render and submit time.</p><h2 id="how-to-modify-element-field-queries-to-change-what-elements-can-be-chosen" tabindex="-1"><a href="/guides/fields/how-to-modify-element-field-queries-to-change-what-elements-can-be-chosen">How to Modify Element Field Queries to Change What Elements Can Be Chosen</a> <a class="header-anchor" href="#how-to-modify-element-field-queries-to-change-what-elements-can-be-chosen" aria-label="Permalink to &quot;[How to Modify Element Field Queries to Change What Elements Can Be Chosen](/guides/fields/how-to-modify-element-field-queries-to-change-what-elements-can-be-chosen)&quot;">​</a></h2><p>Element fields — Entries, Categories, Users, Tags, Products, and Variants — all work the same way underneath: Formie builds an element query from the field settings, then renders that list as a dropdown, radio buttons, checkboxes, or multi-select. That is much more efficient than copying hundreds of options into a static Dropdown field.</p><h2 id="payment-field-with-stripe-—-full-flow" tabindex="-1"><a href="/guides/fields/payment-field-with-stripe-full-flow">Payment Field with Stripe — Full Flow</a> <a class="header-anchor" href="#payment-field-with-stripe-—-full-flow" aria-label="Permalink to &quot;[Payment Field with Stripe — Full Flow](/guides/fields/payment-field-with-stripe-full-flow)&quot;">​</a></h2><p>This walkthrough connects Stripe to a Formie form end to end: integration setup, Payment field configuration, form behaviour, and optional subscription features.</p><h2 id="surveys-polls-and-quizzes-end-to-end" tabindex="-1"><a href="/guides/fields/surveys-polls-and-quizzes-end-to-end">Surveys, Polls and Quizzes End-to-End</a> <a class="header-anchor" href="#surveys-polls-and-quizzes-end-to-end" aria-label="Permalink to &quot;[Surveys, Polls and Quizzes End-to-End](/guides/fields/surveys-polls-and-quizzes-end-to-end)&quot;">​</a></h2><p>Formie separates <strong>questionnaire</strong> use cases into two field types: <strong>Survey</strong> for collecting and aggregating responses, and <strong>Quiz</strong> for scored assessments with pass/fail logic. Simple <strong>polls</strong> — single-question votes — are built with Survey fields using Radio or Dropdown presentation.</p><h2 id="write-your-own-parsing-logic-for-the-calculations-field" tabindex="-1"><a href="/guides/fields/write-your-own-parsing-logic-for-the-calculations-field">Write Your Own Parsing Logic for the Calculations Field</a> <a class="header-anchor" href="#write-your-own-parsing-logic-for-the-calculations-field" aria-label="Permalink to &quot;[Write Your Own Parsing Logic for the Calculations Field](/guides/fields/write-your-own-parsing-logic-for-the-calculations-field)&quot;">​</a></h2><p>The Calculations field evaluates a formula from other field values and shows the result in a read-only input. Formie uses a JavaScript implementation of Symfony Expression Syntax for front-end evaluation. When built-in formatting is not enough — currency display, rounding rules, capping input values before they enter the formula — you can hook into evaluation events and adjust the formula, variables, or result.</p>',20)])])}const p=i(r,[["render",n]]);export{h as __pageData,p as default};
